const body = $input.item.json.body || $input.item.json;
const files = body.files || [];
const namespace = body.namespace || 'default';

if (!Array.isArray(files) || files.length === 0) {
  throw new Error('files array is required. Format: {"files": [{"fileName": "test.txt", "text": "content..."}], "namespace": "default"}');
}

return files.map(file => ({
  json: {
    fileName: file.fileName || 'unknown.txt',
    text: file.text || file.content || '',
    source: (file.fileName || 'unknown').replace('.txt', ''),
    namespace: namespace
  }
}));

const inputItems = $input.all();

return inputItems.map((inputItem, inputIndex) => {
  const inputData = inputItem.json || {};
  const text = inputData.text;
  const source = inputData.source || inputData.fileName || 'unknown';
  const namespace = inputData.namespace || 'default';

  if (!text || typeof text !== 'string') {
    throw new Error(`Text field is required. File: ${source}`);
  }

  const chunkSize = 600;
  const overlap = 100;
  const chunks = [];
  let index = 0;

  for (let i = 0; i < text.length; i += chunkSize - overlap) {
    const chunk = text.slice(i, i + chunkSize);
    if (chunk.trim().length > 0) {
      chunks.push({
        id: `chunk_${source}_${index}`,
        text: chunk,
        chunk_index: index,
        source: source
      });
      index++;
    }
  }

  return {
    json: {
      chunks: chunks,
      namespace: namespace,
      source: source
    },
    pairedItem: { item: inputIndex }
  };
});

const fileItems = $input.all();

return fileItems.map((item, itemIndex) => {
  const { chunks, namespace, source } = item.json;
  if (!Array.isArray(chunks) || chunks.length === 0) {
    throw new Error(`No chunks were created for file ${source || itemIndex + 1}`);
  }

  const documents = chunks.map(chunk => ({
    _id: chunk.id,
    chunk_text: chunk.text,
    title: source,
    source,
    chunk_index: chunk.chunk_index
  }));

  return {
    json: { documents, namespace, documentsCount: documents.length },
    pairedItem: { item: itemIndex }
  };
});

const responses = $input.all();
const formattedItems = $('Format for Pinecone').all();
const filesProcessed = $('Parse Input').all().length;

if (responses.length !== formattedItems.length || responses.length !== filesProcessed) {
  throw new Error(`Upsert item count mismatch: responses=${responses.length}, documents=${formattedItems.length}, files=${filesProcessed}`);
}

let totalUpserted = 0;
const fileResults = responses.map((item, index) => {
  const response = item.json || {};
  const body = response.body && typeof response.body === 'object' ? response.body : response;
  const upsertedCount = body.upserted_count ?? body.upsertedCount;

  if (!Number.isInteger(upsertedCount)) {
    throw new Error(`Pinecone response for file ${index + 1} has no integer upserted_count: ${JSON.stringify(response)}`);
  }
  if (upsertedCount !== formattedItems[index].json.documentsCount) {
    throw new Error(`Pinecone upsert count mismatch for file ${index + 1}: expected=${formattedItems[index].json.documentsCount}, actual=${upsertedCount}`);
  }

  totalUpserted += upsertedCount;
  return { fileIndex: index + 1, upserted: upsertedCount };
});

return [{
  json: {
    status: 'success',
    totalFiles: filesProcessed,
    totalUpserted,
    fileResults
  }
}];
